#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int a, b, t;
} Edge;

int parent[100005];
int size[100005];

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

int unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b)
        return 0;
    if (size[a] < size[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    parent[b] = a;
    size[a] += size[b];
    return 1;
}

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3)
        return 0;

    Edge *edges = malloc((size_t)M * sizeof(Edge));
    for (int i = 0; i < M; i++)
        scanf("%d %d %d", &edges[i].a, &edges[i].b, &edges[i].t);

    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    for (int i = 0; i < M; i++) {
        if (edges[i].t == 1 && !unite(edges[i].a, edges[i].b)) {
            printf("N\n");
            free(edges);
            return 0;
        }
    }

    int removed = 0;
    for (int i = 0; i < M; i++) {
        if (edges[i].t == 2 && !unite(edges[i].a, edges[i].b))
            removed++;
    }

    printf("%c\n", removed <= K ? 'S' : 'N');
    free(edges);
    return 0;
}
